from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

FILES = {
"src/services/mentorshipWorkspace.ts": '''export type WorkspaceStatus = "requested" | "active" | "paused" | "completed" | "closed";
export type WorkspaceRole = "mentor" | "mentee";
export type WorkspacePermission = "view_profile" | "view_weight" | "view_feeding" | "view_sheds" | "view_genetics" | "view_enclosure" | "view_photos" | "view_health";
export type WorkspaceParticipant = { userId: string; role: WorkspaceRole; joinedAt: string };
export type WorkspaceMessage = { id: string; senderId: string; body: string; createdAt: string; editedAt?: string; deletedAt?: string };
export type WorkspaceMilestone = { id: string; title: string; description?: string; status: "planned" | "in-progress" | "complete"; dueAt?: string; updatedAt: string; updatedBy: string };
export type WorkspaceNote = { id: string; authorId: string; body: string; createdAt: string; updatedAt?: string };
export type WorkspaceEvent = { id: string; type: "request" | "accepted" | "permission-changed" | "milestone-updated" | "message" | "completed"; actorId: string; createdAt: string; summary: string };
export type MentorshipWorkspace = { id: string; requestId?: string; goal: string; status: WorkspaceStatus; menteeId: string; mentorId: string; participantUids: string[]; participants: WorkspaceParticipant[]; permissions: Record<WorkspacePermission, boolean>; messages: WorkspaceMessage[]; milestones: WorkspaceMilestone[]; notes: WorkspaceNote[]; events: WorkspaceEvent[]; createdAt: string; updatedAt: string };
export const defaultWorkspacePermissions: Record<WorkspacePermission, boolean> = { view_profile: true, view_weight: false, view_feeding: false, view_sheds: false, view_genetics: false, view_enclosure: false, view_photos: false, view_health: false };
export function canReadPermission(workspace: MentorshipWorkspace, permission: WorkspacePermission, requesterId: string) { return workspace.participantUids.includes(requesterId) && workspace.permissions[permission] === true; }
export function canSendMessage(workspace: MentorshipWorkspace, requesterId: string) { return workspace.status === "active" && workspace.participantUids.includes(requesterId); }
export function revokeAllRecordPermissions(workspace: MentorshipWorkspace) { return { ...workspace, permissions: { ...defaultWorkspacePermissions } }; }
export function createWorkspace(goal: string, menteeId: string, mentorId: string, now = new Date().toISOString()): MentorshipWorkspace { return { id: crypto.randomUUID(), goal, status: "active", menteeId, mentorId, participantUids: [menteeId, mentorId], participants: [{ userId: menteeId, role: "mentee", joinedAt: now }, { userId: mentorId, role: "mentor", joinedAt: now }], permissions: { ...defaultWorkspacePermissions }, messages: [], milestones: [], notes: [], events: [{ id: crypto.randomUUID(), type: "accepted", actorId: mentorId, createdAt: now, summary: "Mentorship workspace created." }], createdAt: now, updatedAt: now }; }
''',
"src/services/mentorshipService.ts": '''import { addDoc, collection, doc, getDoc, getDocs, limit, orderBy, query, serverTimestamp, updateDoc, writeBatch, where } from "firebase/firestore";
import { auth, db } from "../firebase/config";
import type { MentorshipRequest, MentorshipRequestStatus } from "./mentorNetwork";
import { createWorkspace, defaultWorkspacePermissions, type MentorshipWorkspace, type WorkspacePermission } from "./mentorshipWorkspace";
const requests = collection(db, "mentorshipRequests");
const workspaces = collection(db, "mentorshipWorkspaces");
function requireUserId() { const uid = auth.currentUser?.uid; if (!uid) throw new Error("You must be signed in to use mentorship."); return uid; }
function toIso(value: unknown): string | undefined { if (value && typeof value === "object" && "toDate" in value && typeof (value as {toDate?:unknown}).toDate === "function") return (value as {toDate:()=>Date}).toDate().toISOString(); return typeof value === "string" ? value : undefined; }
function mapRequest(id: string, data: Record<string, unknown>): MentorshipRequest { return { id, requesterId: String(data.requesterId ?? ""), mentorId: String(data.mentorId ?? ""), goal: String(data.goal ?? ""), message: String(data.message ?? ""), requestedRecords: Array.isArray(data.requestedRecords) ? data.requestedRecords.map(String) : [], status: (data.status ?? "sent") as MentorshipRequestStatus, createdAt: toIso(data.createdAt) ?? new Date().toISOString(), updatedAt: toIso(data.updatedAt), acceptedAt: toIso(data.acceptedAt), workspaceId: typeof data.workspaceId === "string" ? data.workspaceId : undefined }; }
export async function createMentorshipRequest(input: {mentorId:string; goal:string; message:string; requestedRecords:string[]}): Promise<MentorshipRequest> { const requesterId=requireUserId(); if (!input.mentorId || !input.goal || !input.message.trim()) throw new Error("Mentor, goal and message are required."); if (input.mentorId===requesterId) throw new Error("You cannot request mentorship from yourself."); const existing=await getDocs(query(requests,where("requesterId","==",requesterId),where("mentorId","==",input.mentorId),where("status","in",["sent","accepted"]),limit(1))); if(!existing.empty) throw new Error("You already have an active or pending mentorship with this mentor."); const payload={requesterId,mentorId:input.mentorId,goal:input.goal,message:input.message.trim().slice(0,4000),requestedRecords:input.requestedRecords.slice(0,12),status:"sent",createdAt:serverTimestamp(),updatedAt:serverTimestamp()}; const ref=await addDoc(requests,payload); return {id:ref.id,requesterId,mentorId:input.mentorId,goal:input.goal,message:payload.message,requestedRecords:payload.requestedRecords,status:"sent",createdAt:new Date().toISOString()}; }
export async function listMentorshipRequestsForMentor():Promise<MentorshipRequest[]> { const mentorId=requireUserId(); const snapshot=await getDocs(query(requests,where("mentorId","==",mentorId),orderBy("createdAt","desc"),limit(50))); return snapshot.docs.map(item=>mapRequest(item.id,item.data() as Record<string,unknown>)); }
export async function listMyMentorshipRequests():Promise<MentorshipRequest[]> { const requesterId=requireUserId(); const snapshot=await getDocs(query(requests,where("requesterId","==",requesterId),orderBy("createdAt","desc"),limit(50))); return snapshot.docs.map(item=>mapRequest(item.id,item.data() as Record<string,unknown>)); }
export async function acceptMentorshipRequest(requestId:string):Promise<string> { const mentorId=requireUserId(); const requestRef=doc(db,"mentorshipRequests",requestId); const snapshot=await getDoc(requestRef); if(!snapshot.exists()) throw new Error("Mentorship request not found."); const request=mapRequest(snapshot.id,snapshot.data() as Record<string,unknown>); if(request.mentorId!==mentorId) throw new Error("Only the invited mentor can accept this request."); if(request.status!=="sent") throw new Error("This request is no longer awaiting a response."); const workspaceRef=doc(workspaces); const workspace=createWorkspace(request.goal,request.requesterId,mentorId); const batch=writeBatch(db); batch.set(workspaceRef,{...workspace,id:workspaceRef.id,requestId,createdAt:serverTimestamp(),updatedAt:serverTimestamp()}); batch.update(requestRef,{status:"accepted",workspaceId:workspaceRef.id,acceptedAt:serverTimestamp(),updatedAt:serverTimestamp()}); await batch.commit(); return workspaceRef.id; }
export async function declineMentorshipRequest(requestId:string):Promise<void> { const mentorId=requireUserId(); const ref=doc(db,"mentorshipRequests",requestId); const snapshot=await getDoc(ref); if(!snapshot.exists()) throw new Error("Mentorship request not found."); const request=mapRequest(snapshot.id,snapshot.data() as Record<string,unknown>); if(request.mentorId!==mentorId || request.status!=="sent") throw new Error("This request cannot be declined by this account."); await updateDoc(ref,{status:"declined",updatedAt:serverTimestamp()}); }
export async function getMentorshipWorkspace(workspaceId:string):Promise<MentorshipWorkspace|null> { const userId=requireUserId(); const snapshot=await getDoc(doc(db,"mentorshipWorkspaces",workspaceId)); if(!snapshot.exists()) return null; const data=snapshot.data() as Partial<MentorshipWorkspace>; const participantUids=Array.isArray(data.participantUids)?data.participantUids:[]; if(!participantUids.includes(userId)) throw new Error("You do not have access to this mentorship workspace."); return {...(data as MentorshipWorkspace),id:snapshot.id,participantUids,permissions:{...defaultWorkspacePermissions,...(data.permissions??{})},messages:Array.isArray(data.messages)?data.messages:[],milestones:Array.isArray(data.milestones)?data.milestones:[],notes:Array.isArray(data.notes)?data.notes:[],events:Array.isArray(data.events)?data.events:[]}; }
export async function sendMentorshipMessage(workspaceId:string,body:string):Promise<void> { const userId=requireUserId(); const trimmed=body.trim(); if(!trimmed) throw new Error("Message cannot be empty."); const workspace=await getMentorshipWorkspace(workspaceId); if(!workspace || workspace.status!=="active") throw new Error("This mentorship workspace is not active."); await updateDoc(doc(db,"mentorshipWorkspaces",workspaceId),{messages:[...workspace.messages,{id:crypto.randomUUID(),senderId:userId,body:trimmed.slice(0,4000),createdAt:new Date().toISOString()}],events:[...workspace.events,{id:crypto.randomUUID(),type:"message",actorId:userId,createdAt:new Date().toISOString(),summary:"Mentorship message sent."}],updatedAt:serverTimestamp()}); }
export async function updateWorkspacePermission(workspaceId:string,permission:WorkspacePermission,enabled:boolean):Promise<void> { const userId=requireUserId(); const workspace=await getMentorshipWorkspace(workspaceId); if(!workspace || workspace.menteeId!==userId) throw new Error("Only the keeper can change record-sharing permissions."); await updateDoc(doc(db,"mentorshipWorkspaces",workspaceId),{[`permissions.${permission}`]:enabled,events:[...workspace.events,{id:crypto.randomUUID(),type:"permission-changed",actorId:userId,createdAt:new Date().toISOString(),summary:`${permission} permission ${enabled?"enabled":"revoked"}.`}],updatedAt:serverTimestamp()}); }
export async function closeMentorshipWorkspace(workspaceId:string):Promise<void> { const userId=requireUserId(); const workspace=await getMentorshipWorkspace(workspaceId); if(!workspace) throw new Error("Workspace not found."); await updateDoc(doc(db,"mentorshipWorkspaces",workspaceId),{status:"closed",permissions:{...defaultWorkspacePermissions,view_profile:false},updatedAt:serverTimestamp()}); }
''',
"src/pages/MentorshipRequest.tsx": '''import { useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { createMentorshipRequest } from "../services/mentorshipService";
const recordOptions=["Weight history","Feeding history","Shed history","Genetics information","Enclosure information","Health information"];
export default function MentorshipRequest(){const navigate=useNavigate();const{mentorId}=useParams();const[message,setMessage]=useState("");const[goal,setGoal]=useState("Husbandry confidence");const[records,setRecords]=useState<string[]>(["Weight history","Feeding history","Shed history"]);const[saving,setSaving]=useState(false);const[error,setError]=useState("");async function submit(){if(!mentorId||!message.trim())return;setSaving(true);setError("");try{const request=await createMentorshipRequest({mentorId,goal,message,requestedRecords:records});navigate(`/community/keeper-meets-breeder/request-sent/${request.id}`,{replace:true});}catch(caught){setError(caught instanceof Error?caught.message:"We could not send the request. Please try again.");}finally{setSaving(false);}}return <main className="kmb-page"><section className="kmb-hero"><div className="kmb-hero-mark">📨</div><div className="kmb-hero-copy"><span className="kmb-eyebrow">MENTORSHIP REQUEST</span><h1>Ask for guidance</h1><p>Requesting mentor <strong>{mentorId}</strong>. Share only what you are comfortable discussing.</p></div></section><section className="kmb-section"><label>Primary goal<select value={goal} onChange={e=>setGoal(e.target.value)}><option>Husbandry confidence</option><option>Feeding strategy</option><option>Breeding preparation</option><option>Genetics understanding</option><option>Behaviour and handling</option><option>General keeper development</option></select></label><label>Message<textarea value={message} onChange={e=>setMessage(e.target.value)} maxLength={4000} placeholder="What are you hoping to learn, and what have you tried already?"/></label><h3>Requested record categories</h3><p className="kmb-muted">These are permission requests, not automatic access. The keeper remains in control.</p>{recordOptions.map(record=><label key={record}><input type="checkbox" checked={records.includes(record)} onChange={()=>setRecords(current=>current.includes(record)?current.filter(item=>item!==record):[...current,record])}/>{record}</label>)}{error&&<div className="kmb-error" role="alert">{error}</div>}<button type="button" className="kmb-primary-button" disabled={saving||!message.trim()||!mentorId} onClick={()=>void submit()}>{saving?"Sending…":"Send mentorship request"}</button></section></main>}
''',
"src/pages/BecomeAMentor.tsx": '''import { useState } from "react";import { useNavigate } from "react-router-dom";import { addDoc,collection,serverTimestamp } from "firebase/firestore";import { auth,db } from "../firebase/config";
export default function BecomeAMentor(){const navigate=useNavigate();const[experience,setExperience]=useState("");const[conduct,setConduct]=useState(false);const[saving,setSaving]=useState(false);const[error,setError]=useState("");async function submit(){const uid=auth.currentUser?.uid;if(!uid||!experience.trim()||!conduct)return;setSaving(true);setError("");try{await addDoc(collection(db,"mentorApplications"),{applicantId:uid,status:"submitted",experienceSummary:experience.trim().slice(0,4000),conductAccepted:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});navigate("/community/keeper-meets-breeder",{replace:true});}catch(caught){setError(caught instanceof Error?caught.message:"Application could not be submitted.");}finally{setSaving(false);}}return <main className="kmb-page"><section className="kmb-hero"><div className="kmb-hero-mark">🤝</div><div className="kmb-hero-copy"><span className="kmb-eyebrow">COMMUNITY CONTRIBUTOR</span><h1>Become a TTHC Mentor</h1><p>Mentor status is earned through transparent experience, evidence and constructive community contribution.</p></div></section><section className="kmb-section"><label>Experience summary<textarea value={experience} onChange={e=>setExperience(e.target.value)} placeholder="Describe the areas you can genuinely help with…"/></label><label><input type="checkbox" checked={conduct} onChange={e=>setConduct(e.target.checked)}/> I understand that personal experience is not universal expertise and veterinary boundaries must be respected.</label>{error&&<div className="kmb-error" role="alert">{error}</div>}<button type="button" className="kmb-primary-button" disabled={saving||!experience.trim()||!conduct} onClick={()=>void submit()}>{saving?"Submitting…":"Submit application"}</button></section></main>}
''',
"src/pages/MentorDashboard.tsx": '''import { useEffect,useState } from "react";import { useNavigate } from "react-router-dom";import { acceptMentorshipRequest,declineMentorshipRequest,listMentorshipRequestsForMentor } from "../services/mentorshipService";import type { MentorshipRequest } from "../services/mentorNetwork";
export default function MentorDashboard(){const navigate=useNavigate();const[requests,setRequests]=useState<MentorshipRequest[]>([]);const[loading,setLoading]=useState(true);const[error,setError]=useState("");async function load(){setLoading(true);try{setRequests(await listMentorshipRequestsForMentor());}catch(caught){setError(caught instanceof Error?caught.message:"Unable to load mentorship requests.");}finally{setLoading(false);}}useEffect(()=>{void load();},[]);async function respond(requestId:string,action:"accept"|"decline"){setError("");try{if(action==="accept"){const workspaceId=await acceptMentorshipRequest(requestId);navigate(`/community/keeper-meets-breeder/workspace/${workspaceId}`);}else{await declineMentorshipRequest(requestId);await load();}}catch(caught){setError(caught instanceof Error?caught.message:"Unable to update request.");}}return <main className="kmb-page"><section className="kmb-hero"><div className="kmb-hero-mark">🧭</div><div className="kmb-hero-copy"><span className="kmb-eyebrow">MENTOR CENTRE</span><h1>Mentor Dashboard</h1><p>Review requests, accept only appropriate relationships, and keep record-sharing boundaries explicit.</p></div></section><section className="kmb-section"><h2>Mentorship requests</h2>{loading&&<p>Loading requests…</p>}{error&&<div className="kmb-error" role="alert">{error}</div>}{!loading&&!requests.length&&<p>No mentorship requests yet.</p>}{requests.map(request=><article className="kmb-card" key={request.id}><h3>{request.goal}</h3><p>{request.message}</p><small>Requested records: {request.requestedRecords.join(", ")||"None"}</small>{request.status==="sent"&&<div className="kmb-actions"><button type="button" className="kmb-primary-button" onClick={()=>void respond(request.id,"accept")}>Accept & create workspace</button><button type="button" className="kmb-secondary-button" onClick={()=>void respond(request.id,"decline")}>Decline</button></div>}{request.workspaceId&&<button type="button" className="kmb-secondary-button" onClick={()=>navigate(`/community/keeper-meets-breeder/workspace/${request.workspaceId}`)}>Open workspace</button>}</article>)}</section></main>}
''',
"src/pages/MentorshipWorkspace.tsx": '''import { useEffect,useState } from "react";import { useParams } from "react-router-dom";import { closeMentorshipWorkspace,getMentorshipWorkspace,sendMentorshipMessage,updateWorkspacePermission } from "../services/mentorshipService";import type { MentorshipWorkspace,WorkspacePermission } from "../services/mentorshipWorkspace";
const permissionLabels:Record<WorkspacePermission,string>={view_profile:"Profile",view_weight:"Weight history",view_feeding:"Feeding history",view_sheds:"Shed history",view_genetics:"Genetics",view_enclosure:"Enclosure",view_photos:"Photos",view_health:"Health"};
export default function MentorshipWorkspacePage(){const{workspaceId}=useParams();const[workspace,setWorkspace]=useState<MentorshipWorkspace|null>(null);const[message,setMessage]=useState("");const[loading,setLoading]=useState(true);const[error,setError]=useState("");async function load(){if(!workspaceId)return;setLoading(true);try{setWorkspace(await getMentorshipWorkspace(workspaceId));}catch(caught){setError(caught instanceof Error?caught.message:"Unable to load workspace.");}finally{setLoading(false);}}useEffect(()=>{void load();},[workspaceId]);async function send(){if(!workspaceId||!message.trim())return;try{await sendMentorshipMessage(workspaceId,message);setMessage("");await load();}catch(caught){setError(caught instanceof Error?caught.message:"Message could not be sent.");}}async function permission(key:WorkspacePermission){if(!workspaceId||!workspace)return;try{await updateWorkspacePermission(workspaceId,key,!workspace.permissions[key]);await load();}catch(caught){setError(caught instanceof Error?caught.message:"Permission could not be changed.");}}async function close(){if(!workspaceId)return;if(!window.confirm("Close this mentorship and revoke shared-record permissions?"))return;try{await closeMentorshipWorkspace(workspaceId);await load();}catch(caught){setError(caught instanceof Error?caught.message:"Workspace could not be closed.");}}if(loading)return <main className="kmb-page"><section className="kmb-section"><p>Loading mentorship workspace…</p></section></main>;return <main className="kmb-page"><section className="kmb-hero"><div className="kmb-hero-mark">🤝</div><div className="kmb-hero-copy"><span className="kmb-eyebrow">PRIVATE WORKSPACE</span><h1>{workspace?.goal||"Mentorship workspace"}</h1><p>{workspace?.status==="closed"?"This mentorship is closed and record permissions have been revoked.":"A private space for learning, communication and explicitly agreed record sharing."}</p></div></section>{error&&<section className="kmb-section"><div className="kmb-error" role="alert">{error}</div></section>}{workspace&&<><section className="kmb-section"><h2>Record-sharing permissions</h2><p className="kmb-muted">Only the keeper can enable these permissions. They never grant access to anything else.</p>{(Object.keys(permissionLabels) as WorkspacePermission[]).map(key=><label key={key}><input type="checkbox" checked={workspace.permissions[key]} disabled={workspace.status==="closed"} onChange={()=>void permission(key)}/>{permissionLabels[key]}</label>)}<button type="button" className="kmb-secondary-button" disabled={workspace.status==="closed"} onClick={()=>void close()}>Close mentorship & revoke access</button></section><section className="kmb-section"><h2>Messages</h2><div className="kmb-stack">{workspace.messages.map(item=><article className="kmb-card" key={item.id}><strong>{item.senderId===workspace.menteeId?"Keeper":"Mentor"}</strong><p>{item.body}</p></article>)}{!workspace.messages.length&&<p>No messages yet.</p>}</div>{workspace.status==="active"&&<div className="kmb-actions"><textarea value={message} onChange={e=>setMessage(e.target.value)} maxLength={4000} placeholder="Write a message…"/><button type="button" className="kmb-primary-button" disabled={!message.trim()} onClick={()=>void send()}>Send message</button></div>}</section><section className="kmb-section"><h2>Milestones</h2>{workspace.milestones.length?workspace.milestones.map(item=><article className="kmb-card" key={item.id}><strong>{item.title}</strong><p>{item.description}</p><small>{item.status}</small></article>):<p>No milestones have been agreed yet.</p>}</section></>}</main>}
'''
}

for relative, content in FILES.items():
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")

rules_path = ROOT / "firestore.rules"
rules = rules_path.read_text(encoding="utf-8")
marker = "match /{document=**} { allow read, write: if false; }"
if "match /mentorshipRequests/{requestId}" not in rules:
    block = '''
    match /mentors/{mentorId} {
      allow get, list: if signedIn();
      allow create, update, delete: if isCreator();
    }
    match /mentorApplications/{applicationId} {
      allow create: if signedIn() && request.resource.data.applicantId == request.auth.uid && request.resource.data.status == "submitted";
      allow get: if signedIn() && (isCreator() || resource.data.applicantId == request.auth.uid);
      allow list: if isCreator();
      allow update: if isCreator();
      allow delete: if isCreator();
    }
    match /mentorshipRequests/{requestId} {
      allow create: if signedIn() && request.resource.data.requesterId == request.auth.uid && request.resource.data.status == "sent";
      allow get: if signedIn() && (resource.data.requesterId == request.auth.uid || resource.data.mentorId == request.auth.uid || isCreator());
      allow list: if signedIn() && (isCreator() || resource.data.requesterId == request.auth.uid || resource.data.mentorId == request.auth.uid);
      allow update: if signedIn() && (isCreator() || (resource.data.mentorId == request.auth.uid && resource.data.status == "sent" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "workspaceId", "acceptedAt", "updatedAt"]) && request.resource.data.status in ["accepted", "declined"]) || (resource.data.requesterId == request.auth.uid && resource.data.status == "sent" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "updatedAt"]) && request.resource.data.status == "cancelled"));
      allow delete: if isCreator();
    }
    match /mentorshipWorkspaces/{workspaceId} {
      allow create: if signedIn() && request.auth.uid == request.resource.data.mentorId && request.resource.data.participantUids.hasAll([request.resource.data.mentorId, request.resource.data.menteeId]) && request.resource.data.status == "active";
      allow get: if signedIn() && request.auth.uid in resource.data.participantUids;
      allow list: if false;
      allow update: if signedIn() && request.auth.uid in resource.data.participantUids && (
        request.resource.data.diff(resource.data).affectedKeys().hasOnly(["messages", "events", "updatedAt"]) ||
        (request.auth.uid == resource.data.menteeId && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["permissions", "events", "updatedAt"])) ||
        (request.resource.data.status == "closed" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "permissions", "updatedAt"]))
      );
      allow delete: if false;
    }
'''
    if marker not in rules:
        raise SystemExit("Firestore default-deny marker not found; refusing to rewrite rules unsafely.")
    rules = rules.replace(marker, block + "    " + marker, 1)
    rules_path.write_text(rules, encoding="utf-8")
